const app=document.getElementById('app'),toast=document.getElementById('toast');
let deferredInstallPrompt=null;
if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;document.documentElement.classList.add('pwa-installable');});
window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;document.documentElement.classList.remove('pwa-installable');});
const isAdminPortal=()=>location.pathname==='/admin'||location.pathname==='/admin/'||location.pathname==='/admin.html';
const state={me:null,view:'home',exam:null,questions:[],attemptId:null,timer:null,answers:{},submitting:false,expired:false,currentQuestion:0,reviewMode:false,skippedQuestions:[],chatTimer:null,adminTab:'overview',adminGrade:localStorage.getItem('admin_grade')||'all',adminExamRows:[],adminResourceRows:[],resourceOptional:false,editingExam:null,editingQuestion:null,resourceExamId:null,resourceItems:[],resourceOpened:[],lang:localStorage.getItem('exam_lang')||'en',theme:localStorage.getItem('exam_theme')||'light'};
const uiObserver=new MutationObserver(()=>{if(state.lang==='ar')requestAnimationFrame(translateUI)});uiObserver.observe(app,{childList:true,subtree:true});
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function showToast(msg){toast.textContent=msg;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2600)}
function showErrorModal(message,title='Something went wrong'){closeModal();openModal(`<div class="error-modal"><div class="error-icon">!</div><div class="eyebrow">Error</div><h2>${esc(title)}</h2><p class="muted error-message">${esc(message||'Please try again.')}</p><div class="actions"><button class="btn orange" onclick="closeModal()">OK</button></div></div>`)}
function closeChatModal(){clearInterval(state.chatTimer);state.chatTimer=null;closeModal() }
function parentOpenChat(studentId,studentName){return parentOpenTeacherChat(studentId,studentName)}
