function translateUI(){
  const ar=state.lang==='ar';
  document.documentElement.lang=ar?'ar':'en';
  document.documentElement.dir=ar?'rtl':'ltr';
  if(!ar)return;
  const walker=document.createTreeWalker(app,NodeFilter.SHOW_TEXT);
  const nodes=[];
  while(walker.nextNode())nodes.push(walker.currentNode);
  for(const n of nodes){
    const raw=n.nodeValue, v=raw.trim();
    if(!v)continue;
    if(translations[v]) n.nodeValue=raw.replace(v,translations[v]);
  }
  app.querySelectorAll('input,textarea,select,[aria-label],[title]').forEach(el=>{
    ['placeholder','aria-label','title'].forEach(attr=>{
      const v=el.getAttribute(attr);
      if(v&&translations[v])el.setAttribute(attr,translations[v]);
    });
  });
}

async function api(path,opts={}){const r=await fetch(path,{credentials:'same-origin',headers:{'content-type':'application/json',...(opts.headers||{})},...opts});let d=null;try{d=await r.json()}catch{}if(!r.ok)throw new Error(d?.details||d?.error||'Request failed');return d}
function fmtDate(v){return v?new Date(v.replace(' ','T')+'Z').toLocaleString():''}
function fmtSchedule(v){return v?new Date(v).toLocaleString([], {dateStyle:'medium',timeStyle:'short'}):'Immediately'}
function localInputValue(v){if(!v)return '';const d=new Date(v);if(Number.isNaN(d.getTime()))return '';const p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`}
function scheduleState(e){const now=Date.now(),start=e.available_from?Date.parse(e.available_from):NaN,end=e.expires_at?Date.parse(e.expires_at):NaN;if(Number.isFinite(end)&&now>=end)return 'expired';if(Number.isFinite(start)&&now<start)return 'scheduled';return 'open'}
function layout(content,opts={}){const adminPortal=isAdminPortal();const ar=state.lang==='ar';const auth=adminPortal?(state.me?.admin?`<button class="btn" onclick="logout()">${ar?'تسجيل الخروج':'Logout'}</button>`:''):state.me?.user?`<button class="btn ghost" onclick="go('dashboard')">${ar?'لوحة الطالب':'Student Dashboard'}</button><button class="btn ghost" onclick="go('videos')">🎥 ${ar?'الفيديوهات':'Videos'}</button><button class="btn ghost" onclick="go('pdfs')">📄 ${ar?'PDF':'PDFs'}</button><button class="btn" onclick="logout()">${ar?'تسجيل الخروج':'Logout'}</button>`:`<button class="btn orange" onclick="go('login')">${ar?'دخول الطالب':'Student Login'}</button>`;const mobileItems=adminPortal?(state.me?.admin?`<button onclick="logout();closeMobileMenu()">🚪 ${ar?'تسجيل الخروج':'Logout'}</button>`:''):(state.me?.user?`<button onclick="go('dashboard');closeMobileMenu()">🏠 ${ar?'لوحة الطالب':'Student Dashboard'}</button><button onclick="go('videos');closeMobileMenu()">🎥 ${ar?'الفيديوهات':'Videos'}</button><button onclick="go('pdfs');closeMobileMenu()">📄 ${ar?'ملفات PDF':'PDFs'}</button><button onclick="go('results');closeMobileMenu()">📊 ${ar?'نتائجي':'My Results'}</button><button onclick="toggleLang();closeMobileMenu()">🌐 ${ar?'English':'العربية'}</button><button onclick="toggleTheme();closeMobileMenu()">${state.theme==='dark'?'☀️':'✦'} ${ar?'المظهر':'Theme'}</button><button id="install-app-btn" class="install-app-btn" onclick="installPWA();closeMobileMenu()">📲 ${ar?'تثبيت التطبيق':'Install App'}</button><button onclick="logout();closeMobileMenu()">🚪 ${ar?'تسجيل الخروج':'Logout'}</button>`:`<button onclick="go('login');closeMobileMenu()">🔐 ${ar?'دخول الطالب':'Student Login'}</button>`);return `<div class="shell"><header class="topbar"><a class="brand" href="#" onclick="go('home');return false" aria-label="Exam Platform"><div class="brand-mark" aria-hidden="true">EP</div><div class="brand-name">${ar?'منصة الامتحانات':'Exam Platform'}<small>${ar?'الاختبارات · النتائج · التحليلات':'Exams · Results · Analytics'}</small></div></a><div class="top-actions"><button class="circle-btn mobile-desktop-control" onclick="toggleLang()" aria-label="Language">${ar?'EN':'AR'}</button><button class="circle-btn theme-btn mobile-desktop-control" onclick="toggleTheme()" aria-label="Theme">${state.theme==='dark'?'☼':'✦'}</button>${auth}<button class="mobile-menu-btn" onclick="toggleMobileMenu()" aria-label="Menu">☰</button></div></header><div class="mobile-menu-backdrop" id="mobile-menu-backdrop" onclick="closeMobileMenu()"></div><aside class="mobile-menu" id="mobile-menu" aria-label="Mobile menu"><div class="mobile-menu-head"><b>${ar?'القائمة':'Menu'}</b><button class="icon-btn" onclick="closeMobileMenu()" aria-label="Close">×</button></div><div class="mobile-menu-items">${mobileItems}</div></aside>${content}<footer class="footer">${ar?'منصة الامتحانات · الاختبارات والنتائج والتحليلات':'Exam Platform · Exams, Results & Analytics'}</footer></div>`}
function toggleMobileMenu(){document.body.classList.toggle('mobile-menu-open')}
function closeMobileMenu(){document.body.classList.remove('mobile-menu-open')}
async function installPWA(){if(!deferredInstallPrompt){showToast(state.lang==='ar'?'من قائمة المتصفح اختر إضافة إلى الشاشة الرئيسية.':'Use your browser menu and choose Add to Home screen.');return}deferredInstallPrompt.prompt();try{await deferredInstallPrompt.userChoice}catch{}deferredInstallPrompt=null}
window.addEventListener('keydown',e=>{if(e.key==='Escape')closeMobileMenu()});
async function boot(){applyTheme();try{state.me=await api('/api/auth/me')}catch{}const adminPortal=isAdminPortal();if(adminPortal)state.view=state.me?.admin?'admin':'admin-login';else state.view=state.me?.user?'dashboard':'home';render()}
function isFollowupPortal(){return location.pathname.startsWith('/follow/')||location.pathname.startsWith('/followup')}
async function renderFollowup(){const token=decodeURIComponent(location.pathname.split('/')[2]||'');try{const d=await api(`/api/follow/${encodeURIComponent(token)}`);const ar=state.lang==='ar';const s=d.student||{};const results=Array.isArray(d.results)?d.results:[];const skills=Array.isArray(d.skills)?d.skills:[];const exams=Array.isArray(d.exams)?d.exams:[];const st=d.stats||{};const avg=Number(st.average||0),best=Number(st.best||0);app.innerHTML=layout(`<main class="page followup-page"><div class="dashboard-head"><div><div class="eyebrow">${ar?'متابعة الطالب':'Student Follow-up'}</div><h1>${esc(s.full_name||'Student')}</h1><p class="muted">${esc(s.student_id||'')} · ${esc(s.grade_level||'')} · ${esc(s.group_name||'—')} · ${s.education_system==='azhar'?'Azhar':'General'}</p></div></div><section class="grid grid-4 followup-summary"><div class="card student-stat"><span>${ar?'الاسم':'Name'}</span><b>${esc(s.full_name||'—')}</b></div><div class="card student-stat"><span>${ar?'المرحلة التعليمية':'Educational stage'}</span><b>${esc(s.grade_level||'—')}</b><small>${s.education_system==='azhar'?'Azhar':'General'}</small></div><div class="card student-stat"><span>${ar?'المجموعة':'Group'}</span><b>${esc(s.group_name||'—')}</b></div><div class="card student-stat"><span>${ar?'رقم ولي الأمر':'Parent phone'}</span><b>${esc(s.parent_phone||'—')}</b></div></section><section class="grid grid-4 followup-summary"><div class="card student-stat"><span>${ar?'امتحانات مكتملة':'Completed exams'}</span><b>${st.completed||0}</b></div><div class="card student-stat"><span>${ar?'متوسط الأداء':'Average performance'}</span><b>${avg.toFixed(1)}%</b></div><div class="card student-stat"><span>${ar?'أفضل نتيجة':'Best result'}</span><b>${best.toFixed(1)}%</b></div><div class="card student-stat"><span>${ar?'ناجح':'Passed'}</span><b>${st.passed||0}</b></div></section><section class="card"><div class="eyebrow">${ar?'الامتحانات':'Exams'}</div><h2>${ar?'امتحانات الطالب':'Student exams'}</h2>${exams.length?`<div class="follow-exam-grid">${exams.map(e=>`<div class="card follow-exam"><b>${esc(e.title)}</b><div class="follow-exam-meta">${e.result_id?`<span class="pill ${e.passed?'pass':'fail'}">${Number(e.percentage||0).toFixed(1)}%</span>`:`<span class="pill">${ar?'لم يؤد بعد':'Not taken'}</span>`}</div></div>`).join('')}</div>`:`<div class="empty">${ar?'لا توجد امتحانات متاحة حالياً.':'No assigned exams available.'}</div>`}</section><section class="card"><div class="eyebrow">${ar?'نتائج الامتحانات':'Exam Results'}</div><h2>${ar?'النتائج المسجلة':'Recorded results'}</h2>${results.length?`<div class="table-wrap"><table class="table"><thead><tr><th>${ar?'الامتحان':'Exam'}</th><th>${ar?'الدرجة':'Score'}</th><th>%</th><th>${ar?'الحالة':'Status'}</th><th>${ar?'التاريخ':'Date'}</th></tr></thead><tbody>${results.map(r=>`<tr><td><b>${esc(r.title)}</b></td><td>${esc(r.score)} / ${esc(r.total_points)}</td><td>${Number(r.percentage||0).toFixed(1)}%</td><td><span class="pill ${r.passed?'pass':'fail'}">${r.passed?(ar?'ناجح':'Passed'):(ar?'لم ينجح':'Not passed')}</span></td><td>${fmtDate(r.created_at)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${ar?'لا توجد نتائج بعد.':'No exam results yet.'}</div>`}</section><section class="card"><div class="eyebrow">${ar?'تحليل الأداء':'Performance analysis'}</div><h2>${ar?'إحصائيات الأداء حسب المهارة':'Performance by skill'}</h2>${skills.length?`<div class="skill-report-grid">${skills.map(x=>`<div class="skill-report"><div><b>${esc(x.skill)}</b><small>${x.questions} questions</small></div><strong>${Number(x.percentage||0).toFixed(1)}%</strong><div class="skill-bar"><span style="width:${Math.max(0,Math.min(100,Number(x.percentage)||0))}%"></span></div></div>`).join('')}</div>`:`<div class="empty">${ar?'لا توجد بيانات مهارات بعد.':'No skill data yet.'}</div>`}</section></main>`);if(ar)translateUI()}catch(x){app.innerHTML=layout(`<main class="page"><div class="center"><div class="card"><div class="eyebrow">${state.lang==='ar'?'رابط غير صالح':'Invalid link'}</div><h1>${state.lang==='ar'?'تعذر تحميل بيانات الطالب':'Unable to load student data'}</h1><p class="muted">${esc(x.message||'This follow-up link is invalid or expired.')}</p></div></div></main>`)}}

function render(){if(isFollowupPortal())return renderFollowup();const adminPortal=isAdminPortal();if(adminPortal){if(state.view==='admin'&&state.me?.admin)return renderAdmin();return renderAdminLogin()}if(state.view==='admin-login'||state.view==='admin')state.view='home';if(state.me?.user&&state.view==='home')state.view='dashboard';if(state.view==='login')return renderLogin();if(state.view==='register')return renderRegister();if(state.view==='dashboard'&&state.me?.user)return renderDashboard();if(state.view==='videos'&&state.me?.user)return renderStudentResources('video');if(state.view==='pdfs'&&state.me?.user)return renderStudentResources('pdf');if(state.view==='results'&&state.me?.user)return renderStudentResults();if(state.view==='skills'&&state.me?.user)return renderStudentSkills();if(state.view==='progress'&&state.me?.user)return renderStudentProgress();if(state.view==='reading'&&state.me?.user)return renderStudentReading();if(state.view==='exam'&&state.me?.user)return renderExam();if(state.view==='result')return renderResult(state.lastResult);state.view='home';renderHome()}
function renderHome(){app.innerHTML=layout(`<main class="home-page public-home"><section class="public-hero"><div class="public-copy"><div class="eyebrow">English Learning Platform</div><h1>Better English.<br><span>Clearer progress.</span></h1><p>A modern learning and assessment experience designed by Mr. Zahran Abdel Aty to help students practice, measure progress, and know exactly where they need to improve.</p><div class="public-actions"><div class="public-action-row"><button class="btn orange" onclick="go('login')">Student Login ↗</button></div><div class="trusted-note"><b>No student registration</b><span>Your teacher creates and manages your account.</span></div></div></div><div class="public-teacher"><img src="/teacher.png" alt="Mr. Zahran Abdel Aty, English Teacher"><div><small>YOUR ENGLISH TEACHER</small><b>Mr. Zahran Abdel Aty</b><span>Preparatory & Secondary · General & Azhar</span></div></div></section><section class="public-benefits"><div class="eyebrow">Built for better outcomes</div><h2>More than an online exam.</h2><div class="feature-grid"><div class="feature-card"><span class="feature-icon blue">🎯</span><div><b>Skill-based learning</b><small>Every question can be linked to Vocabulary, Grammar, Reading, Writing, Listening and more.</small></div></div><div class="feature-card"><span class="feature-icon purple">📊</span><div><b>Detailed performance reports</b><small>Students and parents can understand the result instead of seeing one score only.</small></div></div><div class="feature-card"><span class="feature-icon green">📈</span><div><b>Progress over time</b><small>Track improvement from one assessment to the next and celebrate real progress.</small></div></div><div class="feature-card"><span class="feature-icon yellow">💡</span><div><b>Weakness detection</b><small>Identify the skills and topics that need more practice.</small></div></div><div class="feature-card"><span class="feature-icon cyan">📚</span><div><b>Comfortable reading</b><small>Long reading passages are built into the exam and optimized for phones.</small></div></div><div class="feature-card"><span class="feature-icon rose">🔐</span><div><b>Teacher-controlled accounts</b><small>No public registration; student access is created and managed by the teacher.</small></div></div></div></section></main>`)}
function renderAdminLogin(){app.innerHTML=layout(`<main class="page"><div class="center"><div class="card"><div class="eyebrow">Administration</div><h1>Control center.</h1><p class="muted">Authorized administrators only.</p><form class="form" onsubmit="adminLogin(event)"><div class="field"><label>Username</label><input name="username" required autocomplete="username"></div><div class="field"><label>Password</label><input name="password" type="password" required autocomplete="current-password"></div><button class="btn orange">Admin Login</button></form><p class="small-text muted">Student? <span class="link" onclick="go('login')">Student login</span></p></div></div></main>`)}
async function adminLogin(e){e.preventDefault();const f=new FormData(e.target);try{await api('/api/admin/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.me=await api('/api/auth/me');state.view='admin';render()}catch(x){showToast(x.message)}}
function renderLogin(){app.innerHTML=layout(`<main class="page"><div class="center"><div class="card"><div class="eyebrow">Student access</div><h1>Welcome back.</h1><p class="muted">Use your Student ID or email and password.</p><form class="form" onsubmit="studentLogin(event)"><div class="field"><label>Student ID / Email</label><input name="identifier" required autocomplete="username"></div><div class="field"><label>Password</label><input name="password" type="password" required autocomplete="current-password"></div><button class="btn orange">Login</button></form><p class="small-text muted">Student accounts are created by the teacher. Contact your teacher if you do not have login details.</p></div></div></main>`)}
function renderRegister(){app.innerHTML=layout(`<main class="page"><div class="center"><div class="card"><div class="eyebrow">New student</div><h1>Create your account.</h1><p class="muted">Your Student ID is generated automatically. You will see it immediately after registration.</p><form class="form" onsubmit="studentRegister(event)"><div class="field"><label>Full name</label><input name="fullName" required maxlength="120"></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Phone</label><input name="phone" type="tel"></div><div class="field"><label>Password</label><input name="password" type="password" minlength="8" maxlength="128" required></div><button class="btn orange">Register & Get Student ID</button></form><p class="small-text muted">Already registered? <span class="link" onclick="go('login')">Login</span></p></div></div></main>`)}
async function studentLogin(e){e.preventDefault();const f=new FormData(e.target);try{await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.me=await api('/api/auth/me');showToast('Login successful');go('dashboard')}catch(x){showToast(x.message)}}
async function studentRegister(e){e.preventDefault();const f=new FormData(e.target);try{const d=await api('/api/auth/register',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.me=await api('/api/auth/me');app.innerHTML=layout(`<main class="page"><div class="center"><div class="card result-box"><div class="eyebrow">Registration complete</div><h2>Your Student ID</h2><div class="score">${esc(d.studentId)}</div><p class="muted">Save this ID. You can use it or your email to log in.</p><button class="btn orange" onclick="go('dashboard')">Continue to Dashboard</button></div></div></main>`)}catch(x){showToast(x.message)}}
function renderParentLogin(){app.innerHTML=layout(`<main class="student-access page"><div class="access-wrap"><div class="access-brand"><div class="eyebrow">Parent portal</div><h1>Follow your child's progress.</h1><p class="muted">Use the parent account created by the teacher to view linked students, exam results and skill progress.</p></div><div class="card access-card"><div class="access-icon">⌂</div><div class="eyebrow">Secure parent access</div><h2>Parent sign in</h2><form class="form" onsubmit="parentLogin(event)"><div class="field"><label>Username</label><input name="username" required autocomplete="username"></div><div class="field"><label>Password</label><input name="password" type="password" required autocomplete="current-password"></div><button class="btn orange" style="width:100%">Open Parent Dashboard ↗</button></form><div class="access-note"><b>Teacher-controlled account.</b><span>The teacher creates the parent account and links the student profiles.</span></div></div></div></main>`)}
async function parentLogin(e){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{await api('/api/parent/login',{method:'POST',body:JSON.stringify(data)});state.me=await api('/api/auth/me');go('parent-dashboard')}catch(x){showToast(x.message)}}
async function renderParentDashboard(){let d={students:[]};try{d=await api('/api/parent/dashboard')}catch(x){showToast(x.message)}const ar=state.lang==='ar';const students=Array.isArray(d.students)?d.students:[];app.innerHTML=layout(`<main class="page parent-page"><section class="student-welcome"><div class="welcome-copy"><div class="eyebrow">${ar?'متابعة الأبناء':'Parent Follow-up'}</div><h1>${ar?'تابع ابنك بسهولة.':'Follow your child easily.'}</h1><p>${ar?'افتح امتحانات ابنك وتابعها وتواصل مباشرة مع المدرس من خلال المحادثة.':'Open your child\'s exams, follow progress and chat with your child directly.'}</p></div><div class="card parent-summary"><span>${ar?'الأبناء المرتبطون':'Linked children'}</span><strong>${students.length}</strong></div></section>${students.length?students.map(parentStudentCard).join(''):`<div class="card empty">${ar?'لا يوجد أبناء مرتبطون بهذا الحساب.':'No children are linked to this parent account yet.'}</div>`}</main>`);if(ar)translateUI()}
function parentStudentCard(x){const ar=state.lang==='ar';const results=Array.isArray(x.results)?x.results:[];const avg=results.length?results.reduce((a,r)=>a+Number(r.percentage||0),0)/results.length:0;return `<section class="card parent-student-card"><div class="parent-student-head"><div><div class="eyebrow">${ar?'الطالب':'Student'}</div><h2>${esc(x.full_name)}</h2><small>${esc(x.student_id)} · ${esc(x.grade_level||'')}</small></div><span class="pill">${avg.toFixed(1)}%</span></div><div class="parent-actions"><button class="btn orange" onclick="parentOpenExams(${x.id},'${esc(x.full_name).replaceAll("'","&#39;")}')">${ar?'الامتحانات':'Open Exams'} ↗</button><button class="btn ghost" onclick="parentOpenChat(${x.id},'${esc(x.full_name).replaceAll("'","&#39;")}')">${ar?'محادثة مع المدرس':'Chat with Teacher'} 💬</button></div><div class="parent-mini-results">${results.slice(0,4).map(r=>`<div><span>${esc(r.title)}</span><b>${Number(r.percentage||0).toFixed(1)}%</b></div>`).join('')||`<span class="muted">${ar?'لا توجد نتائج بعد.':'No exam results yet.'}</span>`}</div></section>`}
async function parentOpenExams(studentId,studentName){const ar=state.lang==='ar';try{const d=await api(`/api/parent/students/${studentId}/exams`);const exams=Array.isArray(d.exams)?d.exams:[];openModal(`<div class="modal-head"><div><div class="eyebrow">${ar?'امتحانات الطالب':'Student Exams'}</div><h2>${esc(studentName)}</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="stack">${exams.map(e=>`<div class="card parent-exam-row"><div><b>${esc(e.title)}</b><p class="muted">${esc(e.description||'')}</p><small>${e.question_count||0} ${ar?'أسئلة':'questions'} · ${e.duration_minutes} min · ${e.passing_percentage}%</small></div><div class="parent-exam-actions">${e.result_id?`<span class="pill ${e.passed?'pass':'fail'}">${Number(e.percentage||0).toFixed(1)}%</span>`:''}<button class="btn small ghost" onclick="parentViewExam(${studentId},${e.id},'${esc(studentName).replaceAll("'","&#39;")}')">${ar?'فتح':'Open'} ↗</button></div></div>`).join('')||`<div class="empty">${ar?'لا توجد امتحانات متاحة حالياً.':'No exams are available right now.'}</div>`}</div>`)}catch(x){showToast(x.message)}}
async function parentViewExam(studentId,examId,studentName){const ar=state.lang==='ar';try{const d=await api(`/api/parent/students/${studentId}/exams/${examId}`);openModal(`<div class="modal-head"><div><div class="eyebrow">${ar?'معاينة الامتحان':'Exam Preview'}</div><h2>${esc(d.exam.title)}</h2><p class="muted">${esc(studentName)} · ${d.questions.length} ${ar?'أسئلة':'questions'}</p></div><button class="icon-btn" onclick="parentOpenExams(${studentId},'${esc(studentName).replaceAll("'","&#39;")}')">×</button></div><div class="stack">${d.questions.map((q,i)=>`<div class="card"><div class="small-text muted">${ar?'السؤال':'Question'} ${i+1} · ${q.points} ${ar?'نقطة':'point(s)'}</div><b>${esc(q.question_text)}</b><div class="parent-options"><span>A. ${esc(q.option_a)}</span><span>B. ${esc(q.option_b)}</span><span>C. ${esc(q.option_c)}</span><span>D. ${esc(q.option_d)}</span></div></div>`).join('')}</div>`)}catch(x){showToast(x.message)}}
async function parentOpenTeacherChat(studentId,studentName){const ar=state.lang==='ar';clearInterval(state.chatTimer);try{const d=await api(`/api/parent/students/${studentId}/teacher-chat`);const renderMessages=msgs=>(msgs||[]).map(m=>`<div class="chat-bubble ${m.sender_type==='parent'?'mine':'theirs'}"><div>${esc(m.message)}</div><small>${m.sender_type==='parent'?(ar?'ولي الأمر':'Parent'):(ar?'المدرس':'Teacher')} · ${fmtDate(m.created_at)}</small></div>`).join('')||`<div class="empty">${ar?'ابدأ المحادثة مع المدرس.':'Start the conversation with the teacher.'}</div>`;openModal(`<div class="modal-head"><div><div class="eyebrow">${ar?'محادثة مع المدرس':'Teacher Chat'}</div><h2>${esc(studentName)}</h2><p class="muted">${ar?'المحادثة مرتبطة بملف الطالب':'Conversation linked to the student profile'}</p></div><button class="icon-btn" onclick="closeChatModal()">×</button></div><div id="chat-messages" class="chat-messages">${renderMessages(d.messages)}</div><form class="chat-form" onsubmit="parentSendTeacherChat(event,${studentId},'${esc(studentName).replaceAll("'",'&#39;')}')"><input name="message" maxlength="2000" required placeholder="${ar?'اكتب رسالتك للمدرس...':'Write a message to the teacher...'}"><button class="btn orange">${ar?'إرسال':'Send'}</button></form>`);const box=document.getElementById('chat-messages');if(box)box.scrollTop=box.scrollHeight;state.chatTimer=setInterval(async()=>{try{const x=await api(`/api/parent/students/${studentId}/teacher-chat`);const b=document.getElementById('chat-messages');if(b){b.innerHTML=renderMessages(x.messages);b.scrollTop=b.scrollHeight}}catch{}},3000)}catch(x){showToast(x.message)}}
async function parentSendTeacherChat(e,studentId,studentName){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{await api(`/api/parent/students/${studentId}/teacher-chat`,{method:'POST',body:JSON.stringify(data)});e.target.reset();await parentOpenTeacherChat(studentId,studentName)}catch(x){showToast(x.message)}}

async function logout(){await api('/api/auth/logout',{method:'POST'}).catch(()=>{});state.me=null;state.view=(isAdminPortal())?'admin-login':'home';render()}
async function renderDashboard(){let exams=[],results=[];try{[exams,results]=await Promise.all([api('/api/exams'),api('/api/results')])}catch(x){showToast(x.message)}const passed=results.filter(r=>r.passed).length;const avg=results.length?results.reduce((a,r)=>a+Number(r.percentage||0),0)/results.length:0;const best=results.length?Math.max(...results.map(r=>Number(r.percentage||0))):0;app.innerHTML=layout(`<main class="student-home page"><section class="student-welcome"><div class="welcome-copy"><div class="eyebrow">Student dashboard</div><h1>Hi, ${esc(state.me.user.fullName)} 👋</h1><p>Your learning journey is measurable. Take your assigned exams, understand your strengths, and know exactly what to practice next.</p><div class="student-meta"><span>${esc(state.me.user.grade||'Student')}</span><span>${state.me.user.educationSystem==='azhar'?'Azhar':'General'}</span>${state.me.user.groupId?'<span>Group assigned</span>':''}</div></div><div class="teacher-hero"><img src="/teacher.png" alt="English Teacher"><div class="teacher-overlay"><small>YOUR TEACHER</small><b>Mr. Zahran Abdel Aty</b><span>English Teacher</span></div></div></section><section class="parent-value"><div><div class="eyebrow">Why this platform?</div><h2>Not just an exam — a clear learning path.</h2><p>Every answer becomes useful feedback, so the student and parent can see where improvement is needed instead of looking at a score alone.</p></div><div class="value-points"><div><b>🎯 Skill-based assessment</b><span>Vocabulary, Grammar, Reading, Writing, Listening & more.</span></div><div><b>📈 Real progress</b><span>Track improvement across exams, not just one result.</span></div><div><b>💡 Smart feedback</b><span>See strengths, weaknesses and what to practice next.</span></div></div></section><section class="feature-grid"><button class="feature-card" onclick="openStudentExams()"><span class="feature-icon blue">📝</span><div><b>Available Exams</b><small>Assigned assessments with clear timing and instructions.</small></div><span>›</span></button><button class="feature-card" onclick="go('videos')"><span class="feature-icon cyan">🎥</span><div><b>Video Library</b><small>Lessons assigned to your grade and education system.</small></div><span>›</span></button><button class="feature-card" onclick="go('pdfs')"><span class="feature-icon purple">📄</span><div><b>PDF Library</b><small>Notes and study files assigned to your class.</small></div><span>›</span></button><button class="feature-card" onclick="go('results')"><span class="feature-icon purple">📊</span><div><b>My Results</b><small>Detailed scores and performance history.</small></div><span>›</span></button><button class="feature-card" onclick="go('skills')"><span class="feature-icon green">🎯</span><div><b>Skill Analysis</b><small>Know your strongest and weakest English skills.</small></div><span>›</span></button><button class="feature-card" onclick="go('reading')"><span class="feature-icon yellow">📚</span><div><b>Reading Practice</b><small>Long passages are displayed comfortably on mobile.</small></div><span>›</span></button><button class="feature-card" onclick="go('progress')"><span class="feature-icon cyan">🧭</span><div><b>Personal Progress</b><small>See whether your performance is improving over time.</small></div><span>›</span></button></section><section class="student-stats"><div class="card student-stat"><span>Exams completed</span><b>${results.length}</b><small>${passed} passed</small></div><div class="card student-stat"><span>Average score</span><b>${avg.toFixed(0)}%</b><small>Across completed exams</small></div><div class="card student-stat"><span>Best score</span><b>${best.toFixed(0)}%</b><small>Your current peak</small></div><div class="card student-stat"><span>Next step</span><b>${exams.length?'Exam':'Practice'}</b><small>${exams.length?'You have an exam ready':'Keep building your skills'}</small></div></section><section class="section-head dashboard-section-head"><div><div class="eyebrow">Your assessments</div><h2>Ready when you are</h2></div></section><section class="grid grid-3 student-exams">${exams.length?exams.map(examCard).join(''):`<div class="card empty">No active exams are available right now. Your teacher will add them here.</div>`}</section></main>`)}
function examCard(e){const state=scheduleState(e);const scheduled=state==='scheduled';const schedule=scheduled?`<div class="exam-schedule scheduled"><b>Starts ${esc(fmtSchedule(e.available_from))}</b><span>Available for ${e.available_from&&e.expires_at?Math.max(1,Math.round((Date.parse(e.expires_at)-Date.parse(e.available_from))/3600000))+' hours':'a limited window'}</span></div>`:`<div class="exam-schedule"><b>Available now</b>${e.expires_at?`<span>Until ${esc(fmtSchedule(e.expires_at))}</span>`:'<span>No expiry set</span>'}</div>`;return `<article class="card exam-card ${scheduled?'is-scheduled':''}"><div class="exam-card-top"><span class="pill ${e.status==='active'?'active':''}">${scheduled?'Scheduled':e.status}</span>${Number(e.desktop_required)===1?'<span class="device-badge">Desktop required</span>':''}</div><h3>${esc(e.title)}</h3><p class="muted">${esc(e.description||'English assessment')}</p><div class="exam-meta"><span>${e.question_count} questions</span><span>·</span><span>${e.duration_minutes} min</span><span>·</span><span>Pass ${e.passing_percentage}%</span></div>${schedule}${Number(e.resource_count||0)>0?`<div class="learning-path-badge">📚 ${e.resource_gate==='required_all'?'Learning path required':`${e.resource_count} optional prep resource${Number(e.resource_count)===1?'':'s'}`}</div>`:''}<div class="actions" style="margin-top:10px">${Number(e.resource_count||0)>0?`<button class="btn ghost" ${scheduled?'disabled':''} onclick="openExamLearningPath(${e.id})">Study path ↗</button>`:''}<button class="btn ${scheduled?'ghost':'orange'}" ${scheduled?'disabled':''} onclick="startExam(${e.id})">${scheduled?'Not open yet':'Start Exam ↗'}</button></div></article>`}
async function openExamLearningPath(id){try{const gate=await api(`/api/exams/${id}/resources`),resources=Array.isArray(gate.resources)?gate.resources:[];if(!resources.length){showErrorModal('There are no learning resources attached to this exam yet.','Learning path unavailable');return}state.resourceExamId=id;state.resourceItems=resources;state.resourceOpened=(gate.opened||[]).map(Number);state.resourceOptional=gate.exam?.resourceGate!=='required_all';state.view='resources';renderResourceGate()}catch(x){showErrorModal(x.message||'Could not load the learning path','Learning path unavailable')}}
async function startExam(id,skipResources=false){
  try{
    state.resourceOptional=false;
    clearInterval(state.timer);
    if(!skipResources){
      const gate=await api(`/api/exams/${id}/resources`),resources=Array.isArray(gate.resources)?gate.resources:[];
      if(gate.exam?.resourceGate==='required_all'&&resources.length){state.resourceExamId=id;state.resourceItems=resources;state.resourceOpened=(gate.opened||[]).map(Number);state.resourceOptional=false;state.view='resources';renderResourceGate();return}
    }
    state.submitting=false;state.expired=false;state.answers={};state.questions=[];state.currentQuestion=0;state.reviewMode=false;state.skippedQuestions=[];
    const d=await api(`/api/exams/${id}/start`);if(!d?.exam)throw new Error('Exam data could not be loaded');if(!Array.isArray(d.questions))throw new Error('Exam questions could not be loaded');if(!d.attemptId)throw new Error('Exam attempt could not be created');
    state.exam=d.exam;state.questions=d.questions;state.attemptId=d.attemptId;state.startedAt=d.startedAt;state.view='exam';renderExam();startTimer();
  }catch(x){console.error('START EXAM ERROR:',x);showErrorModal(x.message||'Unable to start the exam','Unable to start exam')}
}
function renderResourceGate(optional=!!state.resourceOptional){const items=state.resourceItems||[],opened=new Set((state.resourceOpened||[]).map(Number));const firstPending=items.findIndex(r=>Number(r.required)!==0&&!opened.has(Number(r.id)));app.innerHTML=layout(`<main class="page"><div class="center"><div class="dashboard-head"><div><div class="eyebrow">Learning path</div><h1>${optional?'Study before you start.':'Prepare before the exam.'}</h1><p class="muted">${optional?'These are optional materials selected by your teacher for this exam. You can return to the exam whenever you are ready.':'Your teacher selected these materials as required preparation. We can verify that you opened each resource, but an external video host cannot report exact watch time to this platform.'}</p></div><button class="btn ghost" onclick="go('dashboard')">Back to Dashboard ↗</button></div><section class="card learning-path"><div class="learning-path-head"><div><h2>Your sequence</h2><p class="muted">Open each required item in the order chosen by your teacher.</p></div><span class="pill">${Math.max(0,items.filter(r=>Number(r.required)!==0&&opened.has(Number(r.id))).length)} / ${items.filter(r=>Number(r.required)!==0).length} completed</span></div><div class="resource-list">${items.map((r,i)=>{const done=opened.has(Number(r.id)),locked=Number(r.required)!==0&&firstPending>=0&&i>firstPending&&!done;return `<div class="learning-resource ${done?'done':''} ${locked?'locked':''}"><div class="resource-number">${done?'✓':i+1}</div><div class="resource-info"><b>${esc(r.title)}</b><small>${r.type==='video'?'Video':'PDF'} · ${Number(r.required)===0?'Optional':'Required'}</small></div><button class="btn small ${done?'ghost':'orange'}" ${locked?'disabled':''} onclick="openLearningResource(${r.id})">${done?'Opened':locked?'Locked':'Open ↗'}</button></div>`}).join('')}</div><div class="learning-path-actions"><button class="btn orange" ${optional?'':(firstPending>=0?'disabled':'')} onclick="enterExamAfterResources()">Enter Exam ↗</button><button class="btn ghost" onclick="go('dashboard')">Later</button></div></section></div></main>`)}
async function openLearningResource(resourceId){const r=state.resourceItems.find(x=>Number(x.id)===Number(resourceId));if(!r)return;const firstPending=state.resourceItems.findIndex(x=>Number(x.required)!==0&&!state.resourceOpened.includes(Number(x.id)));const currentIndex=state.resourceItems.findIndex(x=>Number(x.id)===Number(resourceId));if(Number(r.required)!==0&&firstPending>=0&&currentIndex!==firstPending){showErrorModal('Please open the required resources in order.','Complete the learning path');return}try{await api(`/api/exams/${state.resourceExamId}/resources/${resourceId}/open`,{method:'POST'});state.resourceOpened=[...new Set([...state.resourceOpened,Number(resourceId)])];if(r.url)window.open(r.url,'_blank','noopener,noreferrer');renderResourceGate()}catch(x){showErrorModal(x.message||'Could not open this resource','Resource unavailable')}}
function enterExamAfterResources(){startExam(state.resourceExamId,true)}
function examAnsweredCount(){return state.questions.filter(q=>state.answers[q.id]).length}
function examUnanswered(){return state.questions.map((q,i)=>({q,i})).filter(x=>!state.answers[x.q.id])}
function answerQuestion(questionId,answer){state.answers[questionId]=answer;state.skippedQuestions=state.skippedQuestions.filter(i=>state.questions[i]?.id!==questionId);renderExam()}
function nextQuestion(){
  const q=state.questions[state.currentQuestion];
  if(q&&!state.answers[q.id])state.skippedQuestions=[...new Set([...state.skippedQuestions,state.currentQuestion])];
  if(state.currentQuestion<state.questions.length-1){state.currentQuestion++;renderExam();return}
  state.reviewMode=true;renderExam();
}
function previousQuestion(){if(state.currentQuestion>0){state.currentQuestion--;state.reviewMode=false;renderExam()}}
function jumpToQuestion(index){if(index<0||index>=state.questions.length)return;state.currentQuestion=index;state.reviewMode=false;renderExam()}
function renderExam(){
  if(Number(state.exam?.desktop_required)===1 && /Mobi|Android|iPhone|iPad|iPod|Windows Phone/i.test(navigator.userAgent||'')){showDesktopRequiredModal();return}
  const total=state.questions.length, answered=examAnsweredCount(), unanswered=examUnanswered();
  if(!total){app.innerHTML=layout(`<main class="page"><div class="center"><div class="card empty">No questions are available for this assessment.</div></div></main>`);return}
  if(state.reviewMode){
    const missing=unanswered;
    app.innerHTML=layout(`<main class="page"><div class="center"><div class="exam-top"><div><div class="eyebrow">Active assessment</div><b>${esc(state.exam.title)}</b></div><div class="timer" id="timer">--:--</div></div><section class="exam-review card"><div class="eyebrow">Final review</div><h1>Review your answers.</h1><p class="muted">You must answer every question before you can submit this assessment.</p><div class="review-stats"><div><b>${answered}</b><span>Answered</span></div><div><b>${total-answered}</b><span>Remaining</span></div></div>${missing.length?`<div class="review-warning"><b>${missing.length} question${missing.length===1?'':'s'} still need an answer.</b><span>Return to each question below before submitting.</span></div>`:`<div class="review-ready"><b>All questions are answered.</b><span>You can submit your assessment now.</span></div>`}<div class="review-question-list">${state.questions.map((q,i)=>{const done=!!state.answers[q.id];return `<button type="button" class="review-question ${done?'is-answered':'is-missing'}" onclick="jumpToQuestion(${i})"><span>Q${i+1}</span><strong>${done?'Answered':'Needs answer'}</strong><em>${done?'✓':'!'}</em></button>`}).join('')}</div><div class="actions exam-actions"><button type="button" class="btn ghost" onclick="jumpToQuestion(${missing.length?missing[0].i:total-1})">${missing.length?'Return to unanswered':'Review last question'}</button><button type="button" class="btn orange" ${missing.length?'disabled':''} onclick="submitExam()">Submit Exam</button><button type="button" class="btn ghost" onclick="if(confirm('Leave the exam? Your in-progress attempt will remain until its timer expires.'))go('dashboard')">Leave</button></div></section></div></main>`);
    return;
  }
  const i=Math.max(0,Math.min(total-1,state.currentQuestion));state.currentQuestion=i;const q=state.questions[i];
  const resourcesHtml='';
  const filesHtml=Array.isArray(q.attachments)&&q.attachments.length?`<div class="question-resources">${q.attachments.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">📎 ${esc(r.name)}</a>`).join('')}</div>`:'';
  const progress=total?((i+1)/total)*100:0;
  app.innerHTML=layout(`<main class="page"><div class="center"><div class="exam-top"><div><div class="eyebrow">Active assessment</div><b>${esc(state.exam.title)}</b></div><div class="timer" id="timer">--:--</div></div>${resourcesHtml}<section class="exam-progress card"><div><span>Question ${i+1} of ${total}</span><b>${answered} / ${total} answered</b></div><div class="progress-track"><span style="width:${progress}%"></span></div></section><section class="question exam-question"><div class="small-text muted">Question ${i+1} · ${q.points} point${q.points==1?'':'s'}</div><div class="question-title">${esc(q.question_text)}</div>${filesHtml}<div class="options">${['A','B','C','D'].map(k=>`<label class="option"><input type="radio" name="currentQuestion" value="${k}" ${state.answers[q.id]===k?'checked':''} onchange="answerQuestion(${q.id},'${k}')"> <b>${k}.</b> <span>${esc(q['option_'+k.toLowerCase()])}</span></label>`).join('')}</div></section><div class="exam-navigation"><button type="button" class="btn ghost" onclick="previousQuestion()" ${i===0?'disabled':''}>Previous</button><div class="exam-nav-center"><span>${state.answers[q.id]?'Answered':'Not answered'}</span>${!state.answers[q.id]?'<small>You can skip this question and return to it during final review.</small>':''}</div><button type="button" class="btn orange" onclick="nextQuestion()">${!state.answers[q.id]?(i===total-1?'Skip & Review':'Skip & Next'):(i===total-1?'Review & Submit':'Next Question')}</button></div><div class="exam-footer-actions"><button type="button" class="btn ghost" onclick="state.reviewMode=true;renderExam()">Review answers (${answered}/${total})</button><button type="button" class="btn ghost" onclick="if(confirm('Leave the exam? Your in-progress attempt will remain until its timer expires.'))go('dashboard')">Leave</button></div></div></main>`);
}
function showDesktopRequiredModal(){openModal(`<div class="device-warning"><div class="device-warning-icon"><span>▣</span></div><div class="eyebrow">Device requirement</div><h2>Desktop or laptop required</h2><p class="muted">This assessment contains case-study material that is designed for a larger screen. You cannot start it from a phone or tablet.</p><div class="device-warning-points"><span><b>01</b> Better case-study visibility</span><span><b>02</b> Easier document and spreadsheet review</span><span><b>03</b> More comfortable answer navigation</span></div><div class="device-warning-note">Please open this assessment from a desktop or laptop to continue.</div><div class="actions"><button class="btn orange" onclick="closeModal();go('dashboard')">Back to Dashboard</button></div></div>`)}
function startTimer(){
  clearInterval(state.timer);
  if(!state.exam||!state.startedAt){
    console.error('Timer data missing',state.exam,state.startedAt);
    return;
  }
  const raw=String(state.startedAt);
  const normalized=raw.includes('T')?raw:raw.replace(' ','T');
  const parsed=Date.parse(normalized.endsWith('Z')?normalized:`${normalized}Z`);
  const duration=Number(state.exam.duration_minutes);
  if(!Number.isFinite(parsed)||!Number.isFinite(duration)||duration<=0){
    console.error('Invalid timer values:',state.startedAt,state.exam.duration_minutes);
    const el=document.getElementById('timer');
    if(el)el.textContent='--:--';
    return;
  }
  const end=parsed+(duration*60000);
  const tick=()=>{
    if(state.view!=='exam'){
      clearInterval(state.timer);
      return;
    }
    const left=Math.max(0,end-Date.now());
    const minutes=Math.floor(left/60000);
    const seconds=Math.floor(left/1000)%60;
    const el=document.getElementById('timer');
    if(el)el.textContent=`${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}`;
    if(left<=0&&!state.submitting){
      clearInterval(state.timer);
      state.expired=true;
      submitExam(null,true);
    }
  };
  tick();
  state.timer=setInterval(tick,1000);
}
async function submitExam(e,expired=false){
  if(e) e.preventDefault();
  if(state.submitting) return;
  if(!state.attemptId){showErrorModal('The exam attempt could not be found. Please return to the dashboard and start again.','Exam session error');return}
  const unanswered=examUnanswered();
  if(!expired&&unanswered.length){
    state.reviewMode=true;state.currentQuestion=unanswered[0].i;renderExam();showToast(`Please answer all ${unanswered.length} remaining question${unanswered.length===1?'':'s'} before submitting.`);return;
  }
  if(!expired&&!confirm('Submit this exam now?')) return;
  state.submitting=true;clearInterval(state.timer);
  const answers=Object.entries(state.answers).map(([questionId,answer])=>({questionId:Number(questionId),answer}));
  try{
    const d=await api(`/api/attempts/${state.attemptId}/submit`,{method:'POST',body:JSON.stringify({answers,expired})});
    if(!d?.result) throw new Error('The exam was submitted but no result was returned');
    state.lastResult=d.result;state.view='result';renderResult(d.result);
  }catch(x){
    console.error('SUBMIT EXAM ERROR:',x);state.submitting=false;showErrorModal(x.message||'Unable to submit the exam','Unable to submit exam');
    if(state.view==='exam')renderExam();
  }
}
function openStudentExams(){go('dashboard');setTimeout(()=>document.querySelector('.student-exams')?.scrollIntoView({behavior:'smooth',block:'start'}),80)}
async function renderStudentResources(type){
  const ar=state.lang==='ar',isVideo=type==='video',title=isVideo?(ar?'الفيديوهات':'Video Library'):(ar?'ملفات PDF':'PDF Library'),icon=isVideo?'🎥':'📄';
  let rows=[];try{rows=await api(`/api/resources?type=${type}`)}catch(x){showErrorModal(x.message||'Could not load resources','Resources unavailable');return}
  app.innerHTML=layout(`<main class="page student-section-page"><div class="dashboard-head"><div><div class="eyebrow">${icon} ${isVideo?'Learning videos':'Study files'}</div><h1>${title}</h1><p class="muted">${isVideo?(ar?'فيديوهات مخصصة لمرحلتك ونظامك الدراسي.':'Videos assigned to your grade and education system.'):(ar?'ملفات PDF مخصصة لمرحلتك ونظامك الدراسي.':'PDF files assigned to your grade and education system.')}</p></div><button class="btn ghost" onclick="go('dashboard')">${ar?'لوحة الطالب':'Back to Dashboard'} ↗</button></div><section class="resource-library-grid">${rows.length?rows.map(r=>`<article class="card library-card ${Number(r.opened)?'is-opened':''}"><div class="library-icon">${r.type==='video'?'🎥':'📄'}</div><div class="library-body"><div class="eyebrow">${r.type==='video'?'Video':'PDF'} ${Number(r.opened)?'· Opened':''}</div><h3>${esc(r.title)}</h3><p class="muted">${esc(r.description||'Assigned learning material')}</p><div class="library-meta"><span>${esc(r.grade_level)}</span><span>${r.education_system==='azhar'?'Azhar':r.education_system==='general'?'General':'All systems'}</span>${r.group_id?'<span>Group-specific</span>':''}</div><button class="btn orange" onclick="openStudentLibraryResource(${r.id},'${esc(r.url).replaceAll("'",'&#39;')}')">${Number(r.opened)?'Open again':'Open'} ↗</button></div></article>`).join(''):`<div class="card empty">${ar?'لا توجد مواد متاحة لمرحلتك ونظامك حالياً.':'No resources are currently available for your grade and education system.'}</div>`}</section></main>`);
}
async function openStudentLibraryResource(id,url){try{window.open(url,'_blank','noopener,noreferrer');await api(`/api/resources/${id}/open`,{method:'POST'});const active=state.view;await renderStudentResources(active==='videos'?'video':'pdf')}catch(x){showErrorModal(x.message||'Could not open this resource','Resource unavailable')}}

async function renderStudentResults(){let results=[];try{results=await api('/api/results')}catch(x){showToast(x.message)}const ar=state.lang==='ar';const avg=results.length?results.reduce((a,r)=>a+Number(r.percentage||0),0)/results.length:0;app.innerHTML=layout(`<main class="page student-section-page"><div class="dashboard-head"><div><div class="eyebrow">${ar?'نتائج الطالب':'My Results'}</div><h1>${ar?'نتائجي':'My results'}</h1><p class="muted">${ar?'راجع درجاتك وتفاصيل أدائك في كل امتحان.':'Review your scores and performance history for every exam.'}</p></div><button class="btn ghost" onclick="go('dashboard')">${ar?'لوحة الطالب':'Back to Dashboard'} ↗</button></div><section class="student-stats"><div class="card student-stat"><span>${ar?'الامتحانات المكتملة':'Completed exams'}</span><b>${results.length}</b></div><div class="card student-stat"><span>${ar?'متوسط الأداء':'Average score'}</span><b>${avg.toFixed(1)}%</b></div><div class="card student-stat"><span>${ar?'النجاح':'Passed'}</span><b>${results.filter(r=>Number(r.passed)===1).length}</b></div><div class="card student-stat"><span>${ar?'أفضل نتيجة':'Best score'}</span><b>${results.length?Math.max(...results.map(r=>Number(r.percentage||0))).toFixed(1):'0.0'}%</b></div></section><section class="card"><div class="eyebrow">${ar?'سجل الامتحانات':'Exam history'}</div><div class="student-result-list">${results.length?results.map(r=>`<div class="student-result-row"><div><b>${esc(r.title||r.examTitle||'Exam')}</b><small>${fmtDate(r.created_at||r.submittedAt)}</small></div><div class="student-result-score"><strong>${Number(r.percentage||0).toFixed(1)}%</strong><span class="pill ${Number(r.passed)===1?'pass':'fail'}">${Number(r.passed)===1?(ar?'ناجح':'Passed'):(ar?'لم ينجح':'Not passed')}</span></div></div>`).join(''):`<div class="empty">${ar?'لم تؤدِ أي امتحانات بعد.':'No completed exams yet.'}</div>`}</div></section></main>`);if(ar)translateUI()}
async function renderStudentSkills(){let d={skills:[]};try{d=await api('/api/student/analytics')}catch(x){showToast(x.message)}const ar=state.lang==='ar';const skills=Array.isArray(d.skills)?d.skills:[];app.innerHTML=layout(`<main class="page student-section-page"><div class="dashboard-head"><div><div class="eyebrow">${ar?'تحليل المهارات':'Skill Analysis'}</div><h1>${ar?'تحليل مهاراتي':'My skill analysis'}</h1><p class="muted">${ar?'تعرف على نقاط القوة والمهارات التي تحتاج إلى مزيد من التدريب.':'See your strongest skills and the areas that need more practice.'}</p></div><button class="btn ghost" onclick="go('dashboard')">${ar?'لوحة الطالب':'Back to Dashboard'} ↗</button></div><section class="card"><div class="skill-report-grid">${skills.length?skills.map(x=>`<div class="skill-report"><div><b>${esc(x.skill)}</b><small>${x.questions} ${ar?'أسئلة':'questions'}</small></div><strong>${Number(x.percentage||0).toFixed(1)}%</strong><div class="skill-bar"><span style="width:${Math.max(0,Math.min(100,Number(x.percentage)||0))}%"></span></div></div>`).join(''):`<div class="empty">${ar?'سيظهر تحليل المهارات بعد أداء امتحان يحتوي على مهارات مصنفة.':'Skill analysis will appear after you complete an exam with skill-tagged questions.'}</div>`}</div></section></main>`);if(ar)translateUI()}
async function renderStudentProgress(){let results=[];try{results=await api('/api/results')}catch(x){showToast(x.message)}const ar=state.lang==='ar';const ordered=[...results].sort((a,b)=>new Date(a.created_at||0)-new Date(b.created_at||0));const first=ordered[0],last=ordered[ordered.length-1];const change=first&&last?Number(last.percentage||0)-Number(first.percentage||0):0;app.innerHTML=layout(`<main class="page student-section-page"><div class="dashboard-head"><div><div class="eyebrow">${ar?'التقدم الشخصي':'Personal Progress'}</div><h1>${ar?'تطوري مع الوقت':'My progress over time'}</h1><p class="muted">${ar?'تابع تغير أدائك من امتحان إلى آخر.':'Track how your performance changes from one exam to the next.'}</p></div><button class="btn ghost" onclick="go('dashboard')">${ar?'لوحة الطالب':'Back to Dashboard'} ↗</button></div><section class="grid grid-3"><div class="card student-stat"><span>${ar?'أول نتيجة':'First score'}</span><b>${first?Number(first.percentage||0).toFixed(1):'0.0'}%</b></div><div class="card student-stat"><span>${ar?'آخر نتيجة':'Latest score'}</span><b>${last?Number(last.percentage||0).toFixed(1):'0.0'}%</b></div><div class="card student-stat"><span>${ar?'التغير':'Change'}</span><b>${change>=0?'+':''}${change.toFixed(1)}%</b></div></section><section class="card"><div class="eyebrow">${ar?'سجل التطور':'Progress history'}</div><div class="student-progress-list">${ordered.length?ordered.map((r,i)=>`<div class="student-progress-row"><span>${i+1}</span><div><b>${esc(r.title||'Exam')}</b><small>${fmtDate(r.created_at||r.submittedAt)}</small></div><strong>${Number(r.percentage||0).toFixed(1)}%</strong></div>`).join(''):`<div class="empty">${ar?'أدِ أول امتحان لبدء متابعة التطور.':'Complete your first exam to start tracking progress.'}</div>`}</div></section></main>`);if(ar)translateUI()}
function renderStudentReading(){const ar=state.lang==='ar';app.innerHTML=layout(`<main class="page student-section-page"><div class="dashboard-head"><div><div class="eyebrow">${ar?'تدريب القراءة':'Reading Practice'}</div><h1>${ar?'تدريب القراءة':'Reading practice'}</h1><p class="muted">${ar?'استخدم الامتحانات المتاحة للتدرب على فقرات القراءة وفهم التفاصيل تحت وقت محدد.':'Use your available exams to practice reading passages, comprehension and timed question solving.'}</p></div><button class="btn ghost" onclick="go('dashboard')">${ar?'لوحة الطالب':'Back to Dashboard'} ↗</button></div><section class="grid grid-3"><div class="card"><div class="feature-icon yellow">📖</div><h3>${ar?'اقرأ أولاً':'Read first'}</h3><p class="muted">${ar?'اقرأ الفقرة كاملة قبل اختيار الإجابة، وحدد الكلمات المفتاحية.':'Read the whole passage first and identify the key words.'}</p></div><div class="card"><div class="feature-icon blue">⏱️</div><h3>${ar?'تدرب تحت الوقت':'Practice with time'}</h3><p class="muted">${ar?'حل الأسئلة في الوقت المحدد كما في الامتحان الحقيقي.':'Solve within the exam time limit to build speed and accuracy.'}</p></div><div class="card"><div class="feature-icon green">🎯</div><h3>${ar?'راجع أخطاءك':'Review mistakes'}</h3><p class="muted">${ar?'بعد ظهور النتيجة، راجع نقاط الضعف وكرر التدريب.':'After the result, review weak areas and practice them again.'}</p></div></section><div class="result-actions"><button class="btn orange" onclick="openStudentExams()">${ar?'فتح الامتحانات':'Open Available Exams'} ↗</button></div></main>`);if(ar)translateUI()}

function renderResult(r){const pct=Math.max(0,Math.min(100,Number(r.percentage)||0));const ar=state.lang==='ar';const passed=!!r.passed;const statusText=passed?(ar?'ناجح':'Passed'):(ar?'لم ينجح':'Not passed');const message=passed?(ar?'لقد اجتزت هذا الامتحان بنجاح.':'Great work — you passed this assessment.'):(ar?'لم تصل إلى درجة النجاح هذه المرة. استمر في التدريب وحاول مرة أخرى.':'This result shows exactly where more practice can help you improve.');const skills=Array.isArray(r.skillBreakdown)?r.skillBreakdown:[];const weak=skills.filter(x=>Number(x.percentage)<70).sort((a,b)=>a.percentage-b.percentage);app.innerHTML=layout(`<main class="page result-page"><div class="result-shell"><div class="result-header"><div><div class="eyebrow">${ar?'اكتمل الامتحان':'Assessment complete'}</div><h1>${esc(r.examTitle)}</h1><p class="muted">${ar?'النتيجة النهائية':'Overall performance'} · ${fmtDate(r.submittedAt||new Date().toISOString())}</p></div><span class="result-status ${passed?'is-pass':'is-fail'}"><span class="status-dot"></span>${statusText}</span></div><section class="result-hero card"><div class="score-ring" style="--score:${pct}%"><div class="score-ring-inner"><strong>${pct.toFixed(1)}%</strong><span>Score</span></div></div><div class="result-summary"><div class="eyebrow">Your progress</div><h2>${message}</h2><p class="muted">The platform breaks the exam down by English skill, so the score becomes a useful learning report.</p></div></section><section class="result-metrics"><div class="result-metric card"><span>Points earned</span><strong>${r.score} <small>/ ${r.totalPoints}</small></strong></div><div class="result-metric card"><span>Pass mark</span><strong>${Number(r.passingPercentage??0).toFixed(0)}%</strong></div><div class="result-metric card"><span>Questions answered</span><strong>${r.answeredCount??'—'} <small>/ ${r.questionCount??'—'}</small></strong></div></section><section class="card result-skills"><div class="eyebrow">Skill report</div><h2>What are you good at — and what needs practice?</h2>${skills.length?`<div class="skill-report-grid">${skills.map(x=>`<div class="skill-report"><div><b>${esc(x.skill)}</b><small>${x.questions} questions</small></div><strong>${Number(x.percentage||0).toFixed(0)}%</strong><div class="skill-bar"><span style="width:${Math.max(0,Math.min(100,Number(x.percentage)||0))}%"></span></div></div>`).join('')}</div>${weak.length?`<div class="weakness-box"><b>🎯 Priority for improvement</b><span>${weak.slice(0,2).map(x=>esc(x.skill)).join(' · ')}</span><small>Focus on these skills in your next practice session.</small></div>`:`<div class="strength-box"><b>🌟 Strong performance across your skills</b><span>Keep practicing to maintain this level.</span></div>`}`:`<div class="empty">Skill analysis will appear when your teacher tags exam questions by skill.</div>`}</section><div class="result-actions">${!passed&&r.examId?`<button class="btn orange" onclick="startExam(${Number(r.examId)})">Retake Exam ↗</button>`:''}<button class="btn ghost" onclick="go('dashboard')">Back to Dashboard ↗</button></div></div></main>`);if(state.lang==='ar')translateUI();}

