async function renderAdmin(){const ar=state.lang==='ar';app.innerHTML=layout(`<div class="admin-layout"><aside class="sidebar"><button class="side-btn ${state.adminTab==='overview'?'active':''}" onclick="adminTab('overview')">${ar?'نظرة عامة':'Overview'}</button><button class="side-btn ${state.adminTab==='students'?'active':''}" onclick="adminTab('students')">${ar?'الطلاب':'Students'}</button><button class="side-btn ${state.adminTab==='exams'?'active':''}" onclick="adminTab('exams')">${ar?'الامتحانات':'Exams'}</button><button class="side-btn ${state.adminTab==='videos'?'active':''}" onclick="adminTab('videos')">🎥 ${ar?'الفيديوهات':'Videos'}</button><button class="side-btn ${state.adminTab==='pdfs'?'active':''}" onclick="adminTab('pdfs')">📄 ${ar?'PDF':'PDFs'}</button><button class="side-btn ${state.adminTab==='results'?'active':''}" onclick="adminTab('results')">${ar?'النتائج':'Results'}</button><button class="side-btn ${state.adminTab==='groups'?'active':''}" onclick="adminTab('groups')">${ar?'المجموعات':'Groups'}</button><button class="side-btn ${state.adminTab==='analytics'?'active':''}" onclick="adminTab('analytics')">${ar?'التحليلات':'Analytics'}</button>${state.me.admin.role==='super_admin'?`<button class="side-btn ${state.adminTab==='admins'?'active':''}" onclick="adminTab('admins')">${ar?'المسؤولون':'Admin Users'}</button>`:''}</aside><main class="admin-main" id="admin-main"></main></div>`);await loadAdminTab()}
function adminTab(t){state.adminTab=t;renderAdmin()}
async function loadAdminTab(){const el=document.getElementById('admin-main');if(!el)return;try{if(state.adminTab==='overview')return await adminOverview(el);if(state.adminTab==='students')return await adminStudents(el);if(state.adminTab==='exams')return await adminExams(el);if(state.adminTab==='videos')return await adminResources(el,'video');if(state.adminTab==='pdfs')return await adminResources(el,'pdf');if(state.adminTab==='results')return await adminResults(el);if(state.adminTab==='groups')return await adminGroups(el);if(state.adminTab==='analytics')return await adminAnalytics(el);if(state.adminTab==='admins')return await adminAdmins(el)}catch(x){console.error('ADMIN TAB ERROR:',x);const ar=state.lang==='ar';el.innerHTML=`<div class="card admin-error"><div class="eyebrow">${ar?'تعذر تحميل البيانات':'Could not load this section'}</div><h2>${ar?'تعذر تحميل لوحة التحكم':'The admin data could not be loaded'}</h2><p class="muted">${ar?'تأكد من تطبيق تحديثات قاعدة البيانات ثم أعد تحميل الصفحة.':'Make sure the latest D1 migrations have been applied, then reload the page.'}</p><button class="btn orange" onclick="adminTab('${state.adminTab}')">${ar?'إعادة المحاولة':'Retry'}</button></div>`}}
async function adminOverview(el){const d=await api('/api/admin/stats'+adminQuery());el.innerHTML=adminYearSelector()+`<div class="dashboard-head"><div><div class="eyebrow">Control center</div><h1>Overview</h1><p class="muted">Manage the assessment platform.</p></div></div><div class="kpis"><div class="card kpi"><div class="muted">Students</div><div class="num">${d.students}</div></div><div class="card kpi"><div class="muted">Exams</div><div class="num">${d.exams}</div></div><div class="card kpi"><div class="muted">Attempts</div><div class="num">${d.attempts}</div></div><div class="card kpi"><div class="muted">Avg. score</div><div class="num">${d.averagePercentage.toFixed(1)}%</div></div></div><div class="grid grid-2 admin-section"><div class="card"><div class="eyebrow">Pass rate</div><div class="score" style="font-size:48px">${d.passRate.toFixed(1)}%</div><p class="muted">Across completed attempts.</p></div><div class="card"><h3>Admin</h3><p class="muted">Signed in as <b>${esc(state.me.admin.username)}</b> · ${esc(state.me.admin.role)}</p><button class="btn ghost" onclick="adminTab('exams')">Manage exams →</button></div></div>`}
async function adminStudents(el){const rows=await api('/api/admin/students'+adminQuery());el.innerHTML=adminYearSelector()+`<div class="dashboard-head"><div><div class="eyebrow">People</div><h1>Students</h1></div><div class="toolbar"><input id="studentSearch" placeholder="Search students…" oninput="searchStudents()"><button class="btn ghost" onclick="studentImportForm()">Import Excel</button><a class="btn ghost" href="/student-accounts-template.xlsx" download>Download Template</a><button class="btn ghost" onclick="promoteStudents()">⬆ Promote year</button><button class="btn orange" onclick="studentForm()">+ Add Student</button></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Student ID</th><th>Name</th><th>Email</th><th>Phone</th><th>Parent phone</th><th>Status</th><th>Joined</th><th></th></tr></thead><tbody id="students-body">${studentRows(rows)}</tbody></table></div></div>`}
function studentRows(rows){return rows.map(r=>`<tr><td><button type="button" class="copy-id" title="Copy student ID" onclick="copyStudentId('${esc(r.student_id).replaceAll("'","&#39;")}')"><b>${esc(r.student_id)}</b><span>⧉</span></button></td><td><b>${esc(r.full_name)}</b></td><td>${esc(r.email)}</td><td>${r.phone?`<a class="phone-link" href="tel:${esc(r.phone)}">${esc(r.phone)}</a>`:`<span class="muted">—</span>`}</td><td>${r.parent_phone?`<a class="phone-link" href="tel:${esc(r.parent_phone)}">${esc(r.parent_phone)}</a>`:`<span class="muted">—</span>`}</td><td><span class="pill">${r.status}</span></td><td>${fmtDate(r.created_at)}</td><td><button class="btn small ghost" onclick="studentDetail(${r.id})">Manage</button></td></tr>`).join('')||`<tr><td colspan="8" class="empty">No students found.</td></tr>`}
async function copyStudentId(id){try{await navigator.clipboard.writeText(id);showToast(`Copied ${id}`)}catch{const t=document.createElement('textarea');t.value=id;document.body.appendChild(t);t.select();document.execCommand('copy');t.remove();showToast(`Copied ${id}`)}}
async function promoteStudents(){
  const ok=confirm('End-of-year promotion: Preparatory 1→2, Preparatory 2→3, Preparatory 3→Secondary 1, Secondary 1→2, Secondary 2→3. All Secondary 3 students will be permanently deleted, including their exam attempts/results. Continue?');
  if(!ok)return;
  const confirm2=confirm('This deletion cannot be undone. Are you sure you want to promote all students now?');
  if(!confirm2)return;
  try{const d=await api('/api/admin/promote',{method:'POST'});showToast(`Promoted ${d.promoted} students; deleted ${d.deletedSecondary3} graduating students.`);adminTab('students')}catch(x){showToast(x.message||'Promotion failed')}
}

let searchTimer;async function searchStudents(){clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{const q=document.getElementById('studentSearch').value;const rows=await api('/api/admin/students'+(q?'?q='+encodeURIComponent(q):adminQuery())+(q&&adminQuery()?'&'+adminQuery().slice(1):''));document.getElementById('students-body').innerHTML=studentRows(rows)},250)}
async function studentDetail(id){const d=await api(`/api/admin/students/${id}`);const ar=state.lang==='ar';const link=d.followupUrl||'';openModal(`<div class="modal-head"><div><div class="eyebrow">${ar?'ملف الطالب':'Student account'}</div><h2>${esc(d.student.full_name)}</h2><p class="muted">${ar?'إدارة الحساب ورابط متابعة ولي الأمر.':'Manage the account and the parent follow-up link.'}</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="grid grid-2"><div class="card student-account-card"><div class="account-id-label">Student ID</div><button type="button" class="account-id" onclick="copyStudentId('${esc(d.student.student_id).replaceAll("'","&#39;")}')"><strong>${esc(d.student.student_id)}</strong><span>Copy</span></button><p>${esc(d.student.email)}</p><p><b>Phone:</b> ${d.student.phone?`<a class="phone-link" href="tel:${esc(d.student.phone)}">${esc(d.student.phone)}</a>`:`<span class="muted">Not provided</span>`}</p><p><b>Parent phone:</b> ${d.student.parent_phone?`<a class="phone-link" href="tel:${esc(d.student.parent_phone)}">${esc(d.student.parent_phone)}</a>`:`<span class="muted">Not provided</span>`}</p><span class="pill">${d.student.status}</span><div class="actions" style="margin-top:15px"><button class="btn small ${d.student.status==='active'?'danger':'orange'}" onclick="toggleStudent(${id},'${d.student.status==='active'?'blocked':'active'}')">${d.student.status==='active'?'Block student':'Activate student'}</button><button class="btn small ghost" onclick='studentForm(${JSON.stringify(d.student).replace(/'/g,"&#39;")})'>Edit profile</button><button class="btn small orange" onclick="resetStudentPassword(${id},'${esc(d.student.full_name).replaceAll("'","&#39;")}')">Change password</button></div></div><div class="card"><div class="eyebrow">${ar?'متابعة ولي الأمر':'Parent follow-up'}</div><h3>${ar?'رابط متابعة الطالب':'Student follow-up link'}</h3><p class="muted">${ar?'رابط واحد يفتح بيانات هذا الطالب فقط، بدون حساب لولي الأمر.':'One simple link that shows this student data only. No parent account is required.'}</p>${link?`<input class="followup-link" readonly value="${esc(link)}"><div class="actions" style="margin-top:10px"><button class="btn orange" onclick="copyFollowupLink('${esc(link).replaceAll("'","&#39;")}')">${ar?'نسخ الرابط':'Copy link'}</button><button class="btn small ghost" onclick="openFollowup('${esc(link).replaceAll("'","&#39;")}')">${ar?'فتح':'Open'} ↗</button></div>`:`<button class="btn orange" onclick="generateFollowupLink(${id})">${ar?'إنشاء رابط المتابعة':'Generate follow-up link'}</button>`}</div></div><div class="card" style="margin-top:16px"><div class="eyebrow">${ar?'النتائج':'Exam results'}</div>${d.results.length?`<div class="stack" style="margin-top:12px">${d.results.map(r=>`<div class="statline"><span>${esc(r.title)}</span><span>${Number(r.percentage).toFixed(1)}%</span></div>`).join('')}</div>`:`<p class="muted">No results yet.</p>`}</div><div class="card" style="margin-top:16px"><div class="eyebrow">Skill profile</div><h3>Areas to develop</h3>${(d.skills||[]).map(x=>`<div class="skill-line"><span>${esc(x.skill)}</span><b>${Number(x.percentage||0).toFixed(1)}%</b></div>`).join('')||'<p class="muted">Skill data will appear after tagged questions are completed.</p>'}</div></div>`)}
async function generateFollowupLink(id){try{const d=await api(`/api/admin/students/${id}/followup-link`,{method:'POST'});showToast('Follow-up link generated');studentDetail(id)}catch(x){showToast(x.message)}}
async function copyFollowupLink(link){try{await navigator.clipboard.writeText(link);showToast('Follow-up link copied')}catch{showToast(link)}}
function openFollowup(link){window.open(link,'_blank','noopener,noreferrer')}

async function studentImportForm(){openModal(`<div class="modal-head"><div><div class="eyebrow">Bulk students</div><h2>Import students from Excel</h2><p class="muted">Upload .xlsx, .xls or .csv. Required: Full Name, Email, Grade. Optional: Phone, Parent Phone, Password, Education System, Group ID.</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="card import-help"><b>Example headers</b><p class="muted">Use the template columns: Full Name, Email, Phone, Parent Phone, Password, Education System, Grade, Group ID.</p><p class="small-text"><a href="/student-accounts-template.xlsx" download>Download the student Excel template</a></p><p class="small-text muted">If Password is empty, a temporary password is generated and shown after import.</p></div><div class="form"><div class="field"><label>Excel file</label><input id="studentExcelFile" type="file" accept=".xlsx,.xls,.csv"></div><button class="btn orange" onclick="importStudentsExcel(event)">Import students</button></div><div id="import-result" class="import-result"></div>`)}
async function importStudentsExcel(e){e?.preventDefault();const input=document.getElementById('studentExcelFile'),file=input?.files?.[0];if(!file){showToast('Choose an Excel file first');return}try{if(!window.XLSX)await new Promise((resolve,reject)=>{const sc=document.createElement('script');sc.src='https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js';sc.onload=resolve;sc.onerror=reject;document.head.appendChild(sc)});const data=await file.arrayBuffer(),wb=XLSX.read(data,{type:'array'}),sheet=wb.Sheets[wb.SheetNames[0]],raw=XLSX.utils.sheet_to_json(sheet,{defval:''});const keyMap={'Full Name':'fullName','Name':'fullName','الاسم':'fullName','الاسم بالكامل':'fullName','Email':'email','البريد الإلكتروني':'email','Phone':'phone','رقم الهاتف':'phone','Parent Phone':'parentPhone','Parent phone':'parentPhone','رقم ولي الامر':'parentPhone','رقم ولي الأمر':'parentPhone','Password':'password','كلمة المرور':'password','Education System':'educationSystem','System':'educationSystem','النظام':'educationSystem','Grade':'grade','المرحلة التعليمية':'grade','الصف':'grade','Group ID':'groupId','معرف المجموعة':'groupId'};const students=raw.map(row=>Object.fromEntries(Object.entries(row).map(([k,v])=>[keyMap[String(k).trim()]||String(k).trim(),String(v??'').trim()])));const d=await api('/api/admin/students/import',{method:'POST',body:JSON.stringify({students})});window.lastImportedStudents=d.created||[];const box=document.getElementById('import-result');box.innerHTML=`<div class="card"><div style="display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap"><div><b>Created: ${d.created?.length||0}</b><br><b>Skipped: ${d.errors?.length||0}</b></div>${d.created?.length?`<button class="btn orange" onclick="sendImportedCredentials()">✉ Send login details by email</button>`:''}</div>${d.created?.length?`<div class="table-wrap" style="margin-top:12px"><table class="table"><thead><tr><th>Student ID</th><th>Name</th><th>Email</th><th>Temporary password</th></tr></thead><tbody>${d.created.map(x=>`<tr><td>${esc(x.studentId)}</td><td>${esc(x.name)}</td><td>${esc(x.email)}</td><td><code>${esc(x.password)}</code></td></tr>`).join('')}</tbody></table></div>`:''}${d.errors?.length?`<div class="import-errors">${d.errors.map(x=>`<div>Row ${x.row}: ${esc(x.error)}</div>`).join('')}</div>`:''}</div>`;showToast(`Imported ${d.created?.length||0} students`)}catch(x){showToast(x.message||'Excel import failed')}}
async function sendImportedCredentials(){const students=window.lastImportedStudents||[];if(!students.length){showToast('No imported students to email');return}const btn=[...document.querySelectorAll('#import-result button')].find(b=>b.textContent.includes('Send login'));if(btn){btn.disabled=true;btn.textContent='Sending…'}try{const d=await api('/api/admin/students/send-credentials',{method:'POST',body:JSON.stringify({students})});showToast(`Login details sent to ${d.sentCount} students`);if(btn){btn.textContent='✓ Emails sent';btn.disabled=true}}catch(x){if(btn){btn.disabled=false;btn.textContent='✉ Send login details by email'}showToast(x.message||'Could not send emails')}}
async function questionManager(examId,title){let qs=[];try{qs=await api(`/api/admin/exams/${examId}/questions`)}catch(x){showErrorModal(x.message||'Unable to load the questions for this exam','Question bank unavailable');return}const examTitle=title||'Question Bank';openModal(`<div class="modal-head"><div><div class="eyebrow">Question bank</div><h2>${esc(examTitle)}</h2><p class="muted">Add questions manually or import up to 200 questions from Excel.</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="actions" style="margin-bottom:15px;flex-wrap:wrap"><button type="button" class="btn orange" onclick="questionForm(${examId},null)">+ Add Question</button><button type="button" class="btn ghost" onclick="questionImportForm(${examId})">Import Excel</button><a class="btn ghost" href="/question-import-template.xlsx" download>Download Template</a></div><div class="stack">${qs.map((q,i)=>{return `<div class="card"><div class="small-text muted">Question ${i+1} · ${q.points} point${q.points==1?'':'s'} · Correct answer ${q.correct_answer}</div><b>${esc(q.question_text)}</b><p class="small-text muted">A. ${esc(q.option_a)} · B. ${esc(q.option_b)} · C. ${esc(q.option_c)} · D. ${esc(q.option_d)}</p><div class="actions"><button type="button" class="btn small ghost" onclick="editQuestionById(${q.id},${examId})">Edit</button><button type="button" class="btn small danger" onclick="deleteQuestion(${q.id},${examId})">Delete</button></div></div>`}).join('')||`<div class="empty">No questions yet.</div>`}</div>`)}
async function editQuestionById(id,examId){try{const qs=await api(`/api/admin/exams/${examId}/questions`);const q=(qs||[]).find(x=>Number(x.id)===Number(id));if(!q)throw new Error('Question not found');questionForm(examId,q)}catch(x){showErrorModal(x.message||'Unable to open the question','Question unavailable')}}
async function loadXLSX(){if(window.XLSX)return window.XLSX;if(window.__xlsxPromise)return window.__xlsxPromise;window.__xlsxPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js';script.onload=()=>resolve(window.XLSX);script.onerror=()=>reject(new Error('Could not load the Excel reader. Check your internet connection and try again.'));document.head.appendChild(script)});return window.__xlsxPromise}
function questionImportForm(examId,title){openModal(`<div class="modal-head"><div><div class="eyebrow">Bulk question import</div><h2>Import questions from Excel</h2><p class="muted">Use the template columns: Question, Option A, Option B, Option C, Option D, Skill, Correct Answer, Points, Sort Order. Skill is imported automatically.</p></div><button class="icon-btn" onclick="questionManager(${examId})">×</button></div><div class="card import-help"><b>How it works</b><ol class="small-text"><li>Download the template.</li><li>Fill one question per row.</li><li>Save as .xlsx.</li><li>Choose the file below and review the detected rows.</li></ol></div><form class="form" onsubmit="previewQuestionImport(event,${examId})"><div class="field"><label>Excel file (.xlsx / .xls)</label><input id="questionExcelFile" name="excelFile" type="file" accept=".xlsx,.xls" required></div><button class="btn orange">Read Excel</button></form>`)}
function excelValue(row,keys){
  if(!row||typeof row!=='object') return '';
  const entries=Object.entries(row);
  const normalize=v=>String(v??'').replace(/\ufeff/g,'').trim().toLowerCase().replace(/[\s_\-]+/g,'');
  for(const key of keys){
    const exact=entries.find(([k])=>String(k).replace(/\ufeff/g,'').trim()===String(key).trim());
    if(exact && exact[1]!==undefined && exact[1]!==null && String(exact[1]).trim()!=='') return exact[1];
  }
  const wanted=keys.map(normalize);
  const match=entries.find(([k])=>wanted.includes(normalize(k)));
  return match?.[1] ?? '';
}
async function previewQuestionImport(e,examId,title){e.preventDefault();const file=e.target.excelFile.files?.[0];if(!file)return;try{const XLSX=await loadXLSX();const data=await file.arrayBuffer();const wb=XLSX.read(data,{type:'array'});const ws=wb.Sheets[wb.SheetNames[0]];const rows=XLSX.utils.sheet_to_json(ws,{defval:'',raw:false});const questions=rows.map((r,i)=>({questionText:String(excelValue(r,['Question','Question Text','question_text'])).trim(),optionA:String(excelValue(r,['Option A','A','option_a'])).trim(),optionB:String(excelValue(r,['Option B','B','option_b'])).trim(),optionC:String(excelValue(r,['Option C','C','option_c'])).trim(),optionD:String(excelValue(r,['Option D','D','option_d'])).trim(),correctAnswer:String(excelValue(r,['Correct Answer','Correct','correct_answer'])).trim().toUpperCase(),points:Number(excelValue(r,['Points','points'])||1),sortOrder:Number(excelValue(r,['Sort Order','Order','sort_order'])||i+1),skill:String(excelValue(r,['Skill','skill'])).trim(),topic:String(excelValue(r,['Topic','Sub-skill','topic'])).trim()})).filter(q=>q.questionText||q.optionA||q.optionB||q.optionC||q.optionD);if(!questions.length)throw new Error('No question rows were found in the first sheet.');if(questions.length>200)throw new Error('Maximum 200 questions per import.');const invalid=questions.findIndex(q=>!q.questionText||!q.optionA||!q.optionB||!q.optionC||!q.optionD||!['A','B','C','D'].includes(q.correctAnswer)||!Number.isFinite(q.points)||q.points<=0||!Number.isInteger(q.sortOrder));if(invalid>=0)throw new Error(`Invalid data in imported row ${invalid+2}. Check all required columns and Correct Answer (A/B/C/D).`);window.__pendingQuestionImport={examId,questions};openModal(`<div class="modal-head"><div><div class="eyebrow">Import preview</div><h2>${questions.length} questions detected</h2><p class="muted">Review the first few rows, then confirm the import.</p></div><button class="icon-btn" onclick="questionManager(${examId})">×</button></div><div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>Question</th><th>A</th><th>B</th><th>C</th><th>D</th><th>Correct</th><th>Points</th></tr></thead><tbody>${questions.slice(0,8).map((q,i)=>`<tr><td>${i+1}</td><td>${esc(q.questionText)}</td><td>${esc(q.optionA)}</td><td>${esc(q.optionB)}</td><td>${esc(q.optionC)}</td><td>${esc(q.optionD)}</td><td><b>${q.correctAnswer}</b></td><td>${q.points}</td></tr>`).join('')}</tbody></table></div>${questions.length>8?`<p class="small-text muted">Showing first 8 of ${questions.length} rows.</p>`:''}<div class="actions"><button class="btn ghost" onclick="questionImportForm(${examId})">Back</button><button class="btn orange" onclick="confirmQuestionImport()">Import ${questions.length} Questions</button></div>`)}catch(x){showErrorModal(x.message||'Unable to read Excel file','Excel import failed')}}
async function confirmQuestionImport(){const pending=window.__pendingQuestionImport;if(!pending?.examId||!Array.isArray(pending.questions))return;try{const d=await api('/api/admin/questions/bulk',{method:'POST',body:JSON.stringify({examId:pending.examId,questions:pending.questions})});delete window.__pendingQuestionImport;await questionManager(pending.examId);showToast(`${d.inserted} questions imported`)}catch(x){showErrorModal(x.message||'Import failed','Question import failed')}}
function questionAttachmentRows(q){let raw=q?.attachments||q?.attachments_json||[];let arr=[];try{arr=Array.isArray(raw)?raw:JSON.parse(raw||'[]')}catch{};if(!arr.length)arr=[{}];return arr.map(questionAttachmentRow).join('')}
function questionAttachmentRow(a={}){return `<div class="attachment-row question-attachment-row"><div class="field"><label>File name</label><input name="questionAttachmentName" maxlength="200" placeholder="e.g. Case study 1" value="${esc(a?.name||'')}"></div><div class="field"><label>File URL</label><input name="questionAttachmentUrl" type="url" maxlength="2000" placeholder="https://..." value="${esc(a?.url||'')}"></div><button type="button" class="btn small ghost" onclick="this.closest('.question-attachment-row').remove()">Remove</button></div>`}
function addQuestionAttachmentRow(){document.getElementById('questionAttachmentRows')?.insertAdjacentHTML('beforeend',questionAttachmentRow())}
async function questionForm(examId,q,title){title=title||'Question Bank';let skills=[];try{skills=await api('/api/admin/skills')}catch{}openModal(`<div class="modal-head"><div><div class="eyebrow">${q?'Edit question':'Add question'}</div><h2>${esc(title)}</h2></div><button class="icon-btn" onclick="questionManager(${examId})">×</button></div><form class="form" onsubmit="saveQuestion(event,${examId},${q?.id||0})"><div class="field"><label>Question</label><textarea name="questionText" rows="4" required>${esc(q?.question_text||'')}</textarea></div><div class="two-col"><div class="field"><label>Option A</label><input name="optionA" required value="${esc(q?.option_a||'')}"></div><div class="field"><label>Option B</label><input name="optionB" required value="${esc(q?.option_b||'')}"></div><div class="field"><label>Option C</label><input name="optionC" required value="${esc(q?.option_c||'')}"></div><div class="field"><label>Option D</label><input name="optionD" required value="${esc(q?.option_d||'')}"></div></div><div class="two-col"><div class="field"><label>Skill</label><select name="skillId"><option value="">Uncategorized</option>${skills.map(x=>`<option value="${x.id}" ${Number(q?.skill_id)===Number(x.id)?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Topic / sub-skill</label><input name="topic" maxlength="120" placeholder="e.g. Conditionals, Synonyms" value="${esc(q?.topic||'')}"></div></div><div class="two-col"><div class="field"><label>Correct answer</label><select name="correctAnswer">${['A','B','C','D'].map(x=>`<option ${q?.correct_answer===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Points</label><input name="points" type="number" min="0.1" step="0.1" value="${q?.points||1}"></div></div><div class="field"><label>Sort order</label><input name="sortOrder" type="number" value="${q?.sort_order||0}"></div><div class="card reading-tip"><b>Reading passages</b><span>For a reading passage, paste the full text into the question field. The student view is optimized for comfortable reading on phones.</span></div><button class="btn orange">Save Question</button></form>`)}
async function saveQuestion(e,examId,id,title){e.preventDefault();const fd=new FormData(e.target);const data=Object.fromEntries(fd);data.examId=examId;try{await api(id?`/api/admin/questions/${id}`:'/api/admin/questions',{method:id?'PUT':'POST',body:JSON.stringify(data)});await questionManager(examId,title);showToast('Question saved')}catch(x){showErrorModal(x.message||'Unable to save the question','Save failed')}}
async function deleteQuestion(id,examId,title){if(!confirm('Delete this question?'))return;try{await api(`/api/admin/questions/${id}`,{method:'DELETE'});await questionManager(examId,title);showToast('Question deleted')}catch(x){showErrorModal(x.message||'Unable to delete the question','Delete failed')}}

async function adminResults(el){const rows=await api('/api/admin/results'+adminQuery());el.innerHTML=adminYearSelector()+`<div class="dashboard-head"><div><div class="eyebrow">Performance</div><h1>Results</h1></div><div class="toolbar"><input id="resultSearch" placeholder="Search results…" oninput="searchResults()"></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Exam</th><th>Score</th><th>Percentage</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody id="results-body">${resultRows(rows)}</tbody></table></div></div>`}
function resultRows(rows){return rows.map(r=>`<tr><td><b>${esc(r.student_id)}</b><div class="small-text muted">${esc(r.full_name)}</div></td><td>${esc(r.title)}</td><td>${r.score}/${r.total_points}</td><td>${Number(r.percentage).toFixed(1)}%</td><td><span class="pill ${r.passed?'pass':'fail'}">${r.passed?'Passed':'Not passed'}</span></td><td>${fmtDate(r.created_at)}</td><td><button class="btn small ghost" onclick="resultDetail(${r.id})">View</button></td></tr>`).join('')||`<tr><td colspan="7" class="empty">No results.</td></tr>`}
let resultTimer;async function searchResults(){clearTimeout(resultTimer);resultTimer=setTimeout(async()=>{const q=document.getElementById('resultSearch').value;const qs=[];if(q)qs.push('q='+encodeURIComponent(q));if(adminQuery())qs.push(adminQuery().slice(1));const rows=await api('/api/admin/results'+(qs.length?'?'+qs.join('&'):''));document.getElementById('results-body').innerHTML=resultRows(rows)},250)}
async function resultDetail(id){const d=await api(`/api/admin/results/${id}`);openModal(`<div class="modal-head"><div><div class="eyebrow">Result detail</div><h2>${esc(d.result.title)}</h2><p class="muted">${esc(d.result.student_id)} · ${esc(d.result.full_name)}</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="grid grid-3"><div class="card"><b>Score</b><div class="score" style="font-size:35px">${Number(d.result.percentage).toFixed(1)}%</div></div><div class="card"><b>Points</b><p>${d.result.score} / ${d.result.total_points}</p></div><div class="card"><b>Status</b><p class="${d.result.passed?'success-text':'danger-text'}">${d.result.passed?'Passed':'Not passed'}</p></div></div><div class="stack" style="margin-top:16px">${d.answers.map((a,i)=>`<div class="card"><b>${i+1}. ${esc(a.question_text)}</b><p class="small-text">Selected: ${a.selected_answer||'No answer'} · Correct: ${a.correct_answer} · ${a.is_correct?'Correct':'Incorrect'}</p></div>`).join('')}</div>`)}
async function adminParents(el){const rows=await api('/api/admin/parents'+adminQuery());const ar=state.lang==='ar';el.innerHTML=adminYearSelector()+`<div class="dashboard-head"><div><div class="eyebrow">${ar?'متابعة الأسر':'Family monitoring'}</div><h1>${ar?'متابعة الوالدين':'Parent Follow-up'}</h1><p class="muted">${ar?'إنشاء حسابات أولياء الأمور وربطهم بالطلاب ومتابعة الأداء.':'Create parent accounts, link students and monitor progress.'}</p></div><button class="btn orange" onclick="parentForm()">+ ${ar?'ولي أمر جديد':'New Parent'}</button></div><div class="grid grid-2">${rows.map(r=>`<div class="card parent-admin-card"><div class="eyebrow">${r.student_count||0} ${ar?'طلاب مرتبطون':'linked students'}</div><h3>${esc(r.full_name)}</h3><p class="muted">@${esc(r.username)} · ${esc(r.email||'')}</p><div class="actions"><button class="btn small ghost" onclick="parentManage(${r.id})">${ar?'إدارة':'Manage'}</button><button class="btn small ghost" onclick="parentForm(${JSON.stringify(r).replace(/'/g,'&#39;')})">${ar?'تعديل':'Edit'}</button><button class="btn small danger" onclick="deleteParent(${r.id})">${ar?'حذف':'Delete'}</button></div></div>`).join('')||`<div class="card empty">${ar?'لا توجد حسابات أولياء أمور.':'No parent accounts yet.'}</div>`}</div>`}
function parentForm(p=null){openModal(`<div class="modal-head"><div><div class="eyebrow">${p?'Edit parent':'Create parent'}</div><h2>${p?'Update parent account':'New parent account'}</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveParent(event,${p?.id||0})"><div class="two-col"><div class="field"><label>Full name</label><input name="fullName" required value="${esc(p?.full_name||'')}"></div><div class="field"><label>Username</label><input name="username" pattern="[A-Za-z0-9._-]{3,80}" required value="${esc(p?.username||'')}" ${p?'readonly':''}></div></div><div class="two-col"><div class="field"><label>Email</label><input name="email" type="email" value="${esc(p?.email||'')}"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(p?.phone||'')}"></div></div>${p?'':'<div class="field"><label>Password</label><input name="password" type="password" minlength="8" required></div>'}<button class="btn orange">${p?'Save Changes':'Create Parent'}</button></form>`)}
async function saveParent(e,id){e.preventDefault();try{await api(id?`/api/admin/parents/${id}`:'/api/admin/parents',{method:id?'PUT':'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();showToast('Parent account saved');adminTab('parents')}catch(x){showToast(x.message)}}
async function parentManage(id){const d=await api(`/api/admin/parents/${id}`);const ar=state.lang==='ar';openModal(`<div class="modal-head"><div><div class="eyebrow">${ar?'حساب ولي الأمر':'Parent account'}</div><h2>${esc(d.parent.full_name)}</h2><p class="muted">@${esc(d.parent.username)}</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="card"><h3>${ar?'الطلاب المرتبطون':'Linked students'}</h3><div class="stack">${(d.students||[]).map(x=>`<div class="statline"><span><b>${esc(x.full_name)}</b><small>${esc(x.student_id)} · ${esc(x.grade_level||'')}</small></span><button class="btn small danger" onclick="unlinkParentStudent(${id},${x.id})">${ar?'إزالة':'Remove'}</button></div>`).join('')||`<p class="muted">${ar?'لا يوجد طلاب مرتبطون.':'No linked students.'}</p>`}</div><form class="form" style="margin-top:15px" onsubmit="linkParentStudent(event,${id})"><div class="field"><label>${ar?'رقم الطالب أو البريد':'Student ID or email'}</label><input name="student" required placeholder="STU-..."></div><button class="btn orange">${ar?'ربط الطالب':'Link student'}</button></form></div>`)}
async function linkParentStudent(e,id){e.preventDefault();try{await api(`/api/admin/parents/${id}/students`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await parentManage(id);showToast('Student linked')}catch(x){showToast(x.message)}}
async function unlinkParentStudent(parentId,studentId){try{await api(`/api/admin/parents/${parentId}/students/${studentId}`,{method:'DELETE'});await parentManage(parentId);showToast('Student unlinked')}catch(x){showToast(x.message)}}
async function deleteParent(id){if(!confirm('Delete this parent account? Linked students will not be deleted.'))return;try{await api(`/api/admin/parents/${id}`,{method:'DELETE'});showToast('Parent deleted');adminTab('parents')}catch(x){showToast(x.message)}}
async function adminAdmins(el){const rows=await api('/api/admin/admins');el.innerHTML=`<div class="dashboard-head"><div><div class="eyebrow">Access control</div><h1>Admin users</h1></div><button class="btn orange" onclick="adminForm()">+ Add Admin</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Username</th><th>Role</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.username)}</b></td><td>${esc(r.role)}</td><td><span class="pill">${r.status}</span></td><td>${fmtDate(r.created_at)}</td><td>${r.id!==undefined?`<button class="btn small ghost" onclick="toggleAdmin(${r.id},'${r.status==='active'?'blocked':'active'}')">${r.status==='active'?'Block':'Activate'}</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`}
async function adminParentChats(el){const ar=state.lang==='ar';const rows=await api('/api/admin/parent-chats');el.innerHTML=adminYearSelector()+`<div class="dashboard-head"><div><div class="eyebrow">${ar?'التواصل مع الأسر':'Family communication'}</div><h1>${ar?'رسائل أولياء الأمور':'Parent Messages'}</h1><p class="muted">${ar?'محادثات مباشرة بين ولي الأمر والمدرس مرتبطة بالطالب.':'Direct conversations between parents and the teacher, linked to the student.'}</p></div></div><div class="grid grid-2">${rows.map(r=>`<button class="card chat-parent-choice" onclick="adminOpenParentChat(${r.parent_id},${r.student_id},'${esc(r.parent_name).replaceAll("'",'&#39;')}','${esc(r.student_name).replaceAll("'",'&#39;')}')"><div class="eyebrow">${esc(r.student_code||'')}</div><h3>${esc(r.parent_name)}</h3><p><b>${esc(r.student_name)}</b></p><p class="muted">${esc(r.last_message||'')}</p><small class="muted">${fmtDate(r.last_message_at)}</small></button>`).join('')||`<div class="card empty">${ar?'لا توجد محادثات حتى الآن.':'No parent conversations yet.'}</div>`}</div>`}
async function adminOpenParentChat(parentId,studentId,parentName,studentName){const ar=state.lang==='ar';clearInterval(state.chatTimer);try{const d=await api(`/api/admin/parent-chats/${parentId}/${studentId}`);const renderMessages=msgs=>(msgs||[]).map(m=>`<div class="chat-bubble ${m.sender_type==='teacher'?'mine':'theirs'}"><div>${esc(m.message)}</div><small>${m.sender_type==='teacher'?(ar?'المدرس':'Teacher'):(ar?'ولي الأمر':'Parent')} · ${fmtDate(m.created_at)}</small></div>`).join('')||`<div class="empty">${ar?'ابدأ المحادثة مع ولي الأمر.':'Start the conversation with the parent.'}</div>`;openModal(`<div class="modal-head"><div><div class="eyebrow">${ar?'محادثة ولي أمر':'Parent Chat'}</div><h2>${esc(parentName)} · ${esc(studentName)}</h2></div><button class="icon-btn" onclick="closeChatModal()">×</button></div><div id="chat-messages" class="chat-messages">${renderMessages(d.messages)}</div><form class="chat-form" onsubmit="adminSendParentChat(event,${parentId},${studentId},'${esc(parentName).replaceAll("'",'&#39;')}','${esc(studentName).replaceAll("'",'&#39;')}')"><input name="message" maxlength="2000" required placeholder="${ar?'اكتب ردك لولي الأمر...':'Write a reply to the parent...'}"><button class="btn orange">${ar?'إرسال':'Send'}</button></form>`);const box=document.getElementById('chat-messages');if(box)box.scrollTop=box.scrollHeight;state.chatTimer=setInterval(async()=>{try{const x=await api(`/api/admin/parent-chats/${parentId}/${studentId}`);const b=document.getElementById('chat-messages');if(b){b.innerHTML=renderMessages(x.messages);b.scrollTop=b.scrollHeight}}catch{}},3000)}catch(x){showToast(x.message)}}
async function adminSendParentChat(e,parentId,studentId,parentName,studentName){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{await api(`/api/admin/parent-chats/${parentId}/${studentId}`,{method:'POST',body:JSON.stringify(data)});e.target.reset();await adminOpenParentChat(parentId,studentId,parentName,studentName)}catch(x){showToast(x.message)}}

function adminForm(){openModal(`<div class="modal-head"><div><div class="eyebrow">Access control</div><h2>Add admin</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><form class="form" onsubmit="saveAdmin(event)"><div class="field"><label>Username</label><input name="username" pattern="[A-Za-z0-9._\-]{3,80}" required></div><div class="field"><label>Password</label><input name="password" type="password" minlength="8" required></div><div class="field"><label>Role</label><select name="role"><option value="admin">Admin</option><option value="super_admin">Super admin</option></select></div><button class="btn orange">Create Admin</button></form>`)}
async function saveAdmin(e){e.preventDefault();try{await api('/api/admin/admins',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();showToast('Admin created');adminTab('admins')}catch(x){showToast(x.message)}}
async function toggleAdmin(id,status){await api(`/api/admin/admins/${id}`,{method:'PATCH',body:JSON.stringify({status})});showToast('Admin status updated');adminTab('admins')}
function openModal(html){const d=document.createElement('div');d.id='modal';d.className='modal-backdrop';d.innerHTML=`<div class="modal">${html}</div>`;document.body.appendChild(d)}function closeModal(){document.getElementById('modal')?.remove()}
function toggleLang(){state.lang=state.lang==='en'?'ar':'en';localStorage.setItem('exam_lang',state.lang);document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';render();requestAnimationFrame(translateUI)}
function toggleTheme(){state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('exam_theme',state.theme);applyTheme();render()}
function applyTheme(){document.body.classList.toggle('dark-mode',state.theme==='dark');document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr'}
function go(v){if(v==='admin-login'){location.href='/admin';return}if(v==='home'){if(location.pathname!=='/admin.html'&&location.pathname!=='/admin')state.view='home';else state.adminTab='overview'}else if(['results','skills','progress','reading','videos','pdfs'].includes(v)){state.view=state.me?.user?v:'login'}else if(v==='dashboard'&&!state.me?.user){state.view='login'}else state.view=v;if(v!=='exam')clearInterval(state.timer);render()}
window.toggleMobileMenu=toggleMobileMenu;window.closeMobileMenu=closeMobileMenu;window.installPWA=installPWA;window.editExamById=editExamById;window.editResourceById=editResourceById;window.generateFollowupLink=generateFollowupLink;window.copyFollowupLink=copyFollowupLink;window.openFollowup=openFollowup;window.answerQuestion=answerQuestion;window.nextQuestion=nextQuestion;window.previousQuestion=previousQuestion;window.jumpToQuestion=jumpToQuestion;window.toggleLang=toggleLang;window.toggleTheme=toggleTheme;window.adminLogin=adminLogin;window.studentLogin=studentLogin;window.studentRegister=studentRegister;window.studentForm=studentForm;window.saveStudent=saveStudent;window.groupForm=groupForm;window.saveGroup=saveGroup;window.deleteGroup=deleteGroup;window.groupManage=groupManage;window.removeStudentFromGroup=removeStudentFromGroup;window.addStudentToGroup=addStudentToGroup;window.moveStudent=moveStudent;window.setAdminGrade=setAdminGrade;window.logout=logout;window.openStudentExams=openStudentExams;window.renderStudentResults=renderStudentResults;window.renderStudentSkills=renderStudentSkills;window.renderStudentProgress=renderStudentProgress;window.renderStudentReading=renderStudentReading;window.startExam=startExam;window.openLearningResource=openLearningResource;window.openStudentLibraryResource=openStudentLibraryResource;window.enterExamAfterResources=enterExamAfterResources;window.showErrorModal=showErrorModal;window.submitExam=submitExam;window.adminTab=adminTab;window.resourceForm=resourceForm;window.saveResource=saveResource;window.deleteResource=deleteResource;window.moveExamResource=moveExamResource;window.searchStudents=searchStudents;window.studentDetail=studentDetail;window.toggleStudent=toggleStudent;window.examForm=examForm;window.addAttachmentRow=addAttachmentRow;window.addQuestionAttachmentRow=addQuestionAttachmentRow;window.saveExam=saveExam;window.deleteExam=deleteExam;window.questionManager=questionManager;window.editQuestionById=editQuestionById;window.questionImportForm=questionImportForm;window.previewQuestionImport=previewQuestionImport;window.confirmQuestionImport=confirmQuestionImport;window.questionForm=questionForm;window.saveQuestion=saveQuestion;window.deleteQuestion=deleteQuestion;window.searchResults=searchResults;window.resultDetail=resultDetail;window.adminForm=adminForm;window.saveAdmin=saveAdmin;window.toggleAdmin=toggleAdmin;window.closeModal=closeModal;
boot();
